// Basic Specifiers
printf("Integer: %d Float: %f Char: %c\n", 10, 3.14, 'Z');
printf("Hex: %#x Octal: %o Scientific: %e\n", 255, 255, 1200.0);

// Width and Padding
printf("Padded: %5d Zero Pad: %05d\n", 42, 42);
printf("Left Justify: %-10s|\n", "Left");

// Precision (Floating Point and String)
printf("Float Prec: %.2f\n", 1.23456); // Shows 1.23
printf("Width/Prec: %8.3f\n", 7.89);    // Total width 8, 3 decimal

// String/Character handling
printf("Max chars: %.4s\n", "ExampleString");
printf("Percent Literal: %%\n");

// Flags
int val = 123;
printf("Address: %p\n", (void*)&val);
printf("Sign Forced: %+d\n", 50);
printf("Space Flag: % d\n", -50); // Adds space for positive numbers
printf("Alt Form Hex: %#X\n", 255); // Prints 0XFF
